<script lang="ts">
	// @ts-expect-error — generated by Wails
	import { GetDisks, GetDiskPartitions } from '@wails/go/gui/App.js';
	// @ts-expect-error — generated by Wails
	import { LogInfo as WailsLogInfo, LogError as WailsLogError } from '@wails/runtime/runtime';

	function logInfo(msg: string): void {
		try { WailsLogInfo(msg); } catch { /* dev mode */ }
	}

	import PageLayout from '$components/PageLayout.svelte';
	import Button from '$components/Button.svelte';
	import { diskSelectionData, pageValid } from '$lib/state.svelte';
	import type { DiskInfo, PartitionDetail } from '$lib/types';
	import { formatSize, FILESYSTEMS } from '$lib/types';

	let disks = $state<DiskInfo[]>([]);
	let selectedDiskId = $state<string>('');
	let partitions = $state<PartitionDetail[]>([]);
	let partitionsLoading = $state(false);
	let loading = $state(true);
	let error = $state<string | null>(null);

	async function loadDisks(): Promise<void> {
		try {
			disks = (await GetDisks()) ?? [];
		} catch (err) {
			error = `Failed to load disks: ${err instanceof Error ? err.message : String(err)}`;
			try { WailsLogError(`[DiskSelectionPage] ${error}`); } catch { /* dev mode */ }
		} finally {
			loading = false;
		}
	}

	async function selectDisk(disk: DiskInfo): Promise<void> {
		selectedDiskId = disk.path;
		diskSelectionData.diskId = disk.path;
		diskSelectionData.disk = disk;
		logInfo(`[DiskSelectionPage] Selected: ${disk.path} (${formatSize(disk.size)})`);

		partitionsLoading = true;
		partitions = [];
		try {
			const parts = await GetDiskPartitions(disk.path);
			partitions = parts ?? [];
		} catch (err) {
			logInfo(`[DiskSelectionPage] Failed to load partitions: ${err}`);
		} finally {
			partitionsLoading = false;
		}
	}

	loadDisks();

	$effect(() => {
		pageValid.value = !!diskSelectionData.diskId && !!diskSelectionData.fileSystem;
	});

	$effect(() => {
		const handler = () => {
			const disk = disks.find(d => d.path === selectedDiskId) ?? null;
			diskSelectionData.diskId = selectedDiskId;
			diskSelectionData.disk = disk;
			logInfo(`[DiskSelectionPage] Syncing to store for validation`);
		};
		document.addEventListener('sync-to-store', handler);
		return () => document.removeEventListener('sync-to-store', handler);
	});
</script>

<PageLayout title="Select Installation Disk">
	<p class="hint">Choose a disk to install AestheticOS. All data on the selected disk will be erased.</p>

	{#if loading}
		<div class="state-message">
			<div class="spinner"></div>
			<p>Scanning for disks...</p>
		</div>
	{:else if error}
		<div class="state-message error">
			<p>{error}</p>
			<Button variant="secondary" onClick={loadDisks}>Retry</Button>
		</div>
	{:else if disks.length === 0}
		<div class="state-message">
			<p>No storage devices found.</p>
		</div>
	{:else}
		<div class="disk-page">
			<!-- Filesystem pills -->
			<div class="fs-bar">
				<span class="fs-label">Filesystem</span>
				<div class="fs-pills">
					{#each FILESYSTEMS as fs (fs)}
						<button
							type="button"
							class={['fs-pill', { selected: diskSelectionData.fileSystem === fs }]}
							onclick={() => { diskSelectionData.fileSystem = fs; }}
						>
							{fs}
						</button>
					{/each}
				</div>
			</div>

			<!-- Disk cards -->
			<div class="disk-list">
				{#each disks as disk (disk.path)}
					<button
						type="button"
						class={['disk-card', { selected: selectedDiskId === disk.path }]}
						onclick={() => selectDisk(disk)}
					>
						<!-- Header: icon + name + radio -->
						<div class="card-header">
							<div class="disk-icon">
								{#if disk.rotational}
									<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">
										<circle cx="12" cy="12" r="10"/>
										<circle cx="12" cy="12" r="3"/>
									</svg>
								{:else}
									<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">
										<path d="M13 2L3 14h9l-1 8 10-12h-9l1-8z"/>
									</svg>
								{/if}
							</div>
							<div class="card-title">
								<div class="disk-name">{disk.model || disk.name}</div>
								<div class="disk-specs">
									{formatSize(disk.size)}
									<span class="specs-sep">·</span>
									{disk.rotational ? 'HDD' : 'SSD'}
									{#if disk.trans}
										<span class="specs-sep">·</span>
										{disk.trans.toUpperCase()}
									{/if}
								</div>
							</div>
							<div class="card-radio">
								<div class={['radio', { checked: selectedDiskId === disk.path }]}></div>
							</div>
						</div>

						<!-- Inline tags -->
						{#if disk.fstype || disk.mountpoint}
							<div class="card-tags">
								{#if disk.fstype}
									<span class="tag fstype">Existing {disk.fstype}</span>
								{/if}
								{#if disk.mountpoint}
									<span class="tag mounted">Mounted {disk.mountpoint}</span>
								{/if}
							</div>
						{/if}

						<!-- Partition details -->
						{#if selectedDiskId === disk.path}
							<div class="card-partitions">
								{#if partitionsLoading}
									<p class="partition-loading">Scanning partitions...</p>
								{:else if partitions.length > 0}
									<table class="partition-table">
										<thead>
											<tr>
												<th>Name</th>
												<th>Type</th>
												<th class="text-right">Size</th>
												<th class="text-right">Mount</th>
											</tr>
										</thead>
										<tbody>
											{#each partitions as part (part.path)}
												<tr>
													<td class="part-name">{part.name}</td>
													<td>
														{#if part.fstype}
															<span class="part-fstype">{part.fstype}</span>
														{:else}
															<span class="part-unknown">—</span>
														{/if}
													</td>
													<td class="text-right">{formatSize(part.size)}</td>
													<td class="text-right">
														{#if part.mountpoint}
															<span class="part-mount">{part.mountpoint}</span>
														{:else}
															<span class="part-empty">—</span>
														{/if}
													</td>
												</tr>
											{/each}
										</tbody>
									</table>
								{:else}
									<p class="partition-empty">No partitions on this disk.</p>
								{/if}
							</div>
						{/if}
					</button>
				{/each}
			</div>
		</div>
	{/if}
</PageLayout>

